package ca.yorku.eecs3311.coursepilot.cli;
import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import ca.yorku.eecs3311.coursepilot.application.service.StudyPlanService; import org.springframework.stereotype.Component; import picocli.CommandLine.*; import java.time.LocalDate;
@Component @Command(name="study-plan",description="Create and list deterministic study plans",mixinStandardHelpOptions=true) public class StudyPlanCommand implements Runnable {private final StudyPlanService plans;private final StudyAgentFacade facade;public StudyPlanCommand(StudyPlanService p,StudyAgentFacade f){plans=p;facade=f;}public void run(){System.out.println("Use 'coursepilot study-plan create --help' or 'study-plan list --help'.");}@Component @Command(name="create",mixinStandardHelpOptions=true)public static class Create implements Runnable{private final StudyPlanCommand p;@Option(names="--course",required=true)String course;@Option(names="--start",required=true)LocalDate start;@Option(names="--target",required=true)LocalDate target;@Option(names="--minutes",required=true)Integer minutes;@Option(names="--strategy",defaultValue="BALANCED")String strategy;public Create(StudyPlanCommand p){this.p=p;}public void run(){var c=p.facade.getCourseByCode(course);var plan=p.plans.create(c.id(),start,target,minutes,strategy);System.out.println("Plan "+plan.id()+" created with "+plan.items().size()+" activities.");}}@Component @Command(name="list",mixinStandardHelpOptions=true)public static class ListPlans implements Runnable{private final StudyPlanCommand p;@Option(names="--course",required=true)String course;public ListPlans(StudyPlanCommand p){this.p=p;}public void run(){var c=p.facade.getCourseByCode(course);p.plans.list(c.id()).forEach(x->System.out.println(x.id()+" "+x.strategy()+" "+x.startDate()+" to "+x.targetDate()));}}}
